Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long double a, b, limit;
    cin >> a >> b >> limit;
    long double min_difference = std::numeric_limits<long double>::max();
    long long numerator = 0, denominator = 1;
    for (int i = 1; i <= limit; ++i) {
        long double val = (a * i) / b;
        long long floor_val = (long long)floor(val);
        if (abs((long double)a / b - (long double)floor_val / i) < min_difference) {
            min_difference = abs((long double)a / b - (long double)floor_val / i);
            numerator = floor_val;
            denominator = i;
        }
        long long ceil_val = (long long)ceil(val);
        if (abs((long double)a / b - (long double)ceil_val / i) < min_difference) {
            min_difference = abs((long double)a / b - (long double)ceil_val / i);
            numerator = ceil_val;
            denominator = i;
        }
    }
    cout << numerator << "/" << denominator;
    return 0;
}
